VersionHelper::useVersioning(function () use ($cart, $cartsFolder): void {
            if (!$cart->getId()) {
                $tempItems = $cart->getItems();
                $cart->setItems([]);

                /**
                 * @psalm-suppress DocblockTypeContradiction
                 */
                if (!$cart->getParent()) {
                    $cart->setParent($cartsFolder);
                }

                $cart->save();
                $cart->setItems($tempItems);
            }

            $items = array_values($cart->getObjectVar('items') ?? []);

            /**
             * @var OrderItemInterface $item
             */
            foreach ($items as $index => $item) {
                $item->setParent(
                    $this->folderCreationService->createFolderForResource(
                        $item,
                        ['prefix' => $cart->getFullPath()],
                    ),
                );
                $item->setKey(uniqid(sprintf('%s.', $index + 1), true));
                $item->setPublished(true);
                $item->save();
            }

            /**
             * The CartProcessor might add new Items to the Cart (eg. Gift Products)
             * so we need to set the Parent and Key after the CartProcessor has been processed
             */
            $this->cartProcessor->process($cart);

            /**
             * @var OrderItemInterface $item
             */
            foreach ($cart->getItems() as $index => $item) {
                $item->setParent(
                    $this->folderCreationService->createFolderForResource(
                        $item,
                        ['prefix' => $cart->getFullPath()],
                    ),
                );
                $item->setKey(uniqid(sprintf('%s.', ((int) $index + 1)), true));
                $item->save();
            }

            $cart->save();
        }, $params['enable_versioning'] ?? false);

$builder
            ->add('amount', MoneyType::class, [
                'constraints' => [
                    new NotBlank(groups: $this->validationGroups),
                    new Type(type: 'numeric', groups: $this->validationGroups),
                    new GreaterThan(value: 0, groups: $this->validationGroups),
                ],
            ])
            ->add('gross', CheckboxType::class, [
            ])
            ->add('applyOn', ChoiceType::class, [
                'choices' => [
                    'total' => 'total',
                    'subtotal' => 'subtotal',
                ],
            ])
            ->add('currency', CurrencyChoiceType::class, [
                'constraints' => [
                    new NotBlank(groups: $this->validationGroups),
                ],
            ])
        ;

$builder
            ->addEventListener(FormEvents::PRE_SET_DATA, function (FormEvent $event): void {
                $type = $this->getRegistryIdentifier($event->getForm(), $event->getData());
                if (null === $type) {
                    return;
                }

                if (!$this->formTypeRegistry->has($type, 'default')) {
                    return;
                }

                $this->addConfigurationFields($event->getForm(), $this->formTypeRegistry->get($type, 'default'));
            })
            ->addEventListener(FormEvents::POST_SET_DATA, function (FormEvent $event): void {
                $type = $this->getRegistryIdentifier($event->getForm(), $event->getData());
                if (null === $type) {
                    return;
                }

                $event->getForm()->get('type')->setData($type);
            })
            ->addEventListener(FormEvents::PRE_SUBMIT, function (FormEvent $event): void {
                $data = $event->getData();

                if (!isset($data['type'])) {
                    return;
                }

                if (!$this->formTypeRegistry->has($data['type'], 'default')) {
                    return;
                }

                $this->addConfigurationFields($event->getForm(), $this->formTypeRegistry->get($data['type'], 'default'));
            })
        ;
